#include <vector>
#include <algorithm>

class Solution {
public:
    int maxSatisfaction(std::vector<int>& satisfaction) {
        std::sort(satisfaction.rbegin(), satisfaction.rend());
        int total = 0, runningSum = 0;
        for (int s : satisfaction) {
            runningSum += s;
            if (runningSum <= 0) break;
            total += runningSum;
        }
        return total;
    }
};

import java.util.*;

class Solution {
    public int maxSatisfaction(int[] satisfaction) {
        Arrays.sort(satisfaction);
        int total = 0, runningSum = 0;
        for (int i = satisfaction.length - 1; i >= 0; i--) {
            runningSum += satisfaction[i];
            if (runningSum <= 0) break;
            total += runningSum;
        }
        return total;
    }
}

var maxSatisfaction = function(satisfaction) {
    satisfaction.sort((a, b) => b - a);
    let total = 0, runningSum = 0;
    for (const s of satisfaction) {
        runningSum += s;
        if (runningSum <= 0) break;
        total += runningSum;
    }
    return total;
};
